     "【表演形式】 独唱+对唱，阿木与阿果隔空对望，情感如火山喷发",
     "【表演形式】 快节奏对白，燕南云与小马哥的干练，彝寨群众的朴实",
     "【表演形式】 对唱，节奏舒缓，充满温情",
     "【表演形式】 低声对白，动作迅捷",
     "【表演形式】 快节奏对白+动作，阿木与追兵的周旋，惊心动魄",
     "舞台被撕裂为两半。左区是嶙峋怪石与枯死的灌木，夕阳如凝血，将阿果奔跑的身影拉长成一道扭曲的剪影。右区是红军接应点的微弱篝火，在风中摇曳，像随时会熄灭的希望。",
     "地面铺满尖锐的碎石与荆棘，每一步都踩出令人牙酸的摩擦声。空气中弥漫着血腥味、尘土味与金沙江潮湿的水汽。",
     "观众席两侧的“追兵”手持火把，形成包围圈，火光映照着他们狰狞的脸。"
