   "lyrics": [
    {
     "speaker": "阿木",
     "cue": "",
     "text": "阿果你是我心上缘，朝朝暮暮岁岁惦念。"
    },
    {
     "speaker": "阿木",
     "cue": "",
     "text": "可父辈热血未凉干，仇人嘴脸犹在眼前。"
    },
    {
     "speaker": "阿木",
     "cue": "",
     "text": "匆匆岁月流转三年，整整三年恨意难掩。"
    },
    {
     "speaker": "阿木",
     "cue": "",
     "text": "阿爹挺身守我乡园，誓死护住彝家山川。"
    },
    {
     "speaker": "阿木",
     "cue": "",
     "text": "他守故土一寸寸天，却遭恶人肆意摧残。"
    },
    {
     "speaker": "阿木",
     "cue": "",
     "text": "拳脚相加寒骨刺穿，枪托砸碎烟火平凡。"
    },
    {
     "speaker": "阿木",
     "cue": "",
     "text": "血泊之中他撑起残年，将彝刀交付我掌间。"
    },
    {
     "speaker": "阿木",
     "cue": "",
     "text": "他嘱我隐忍莫结仇怨，弱小难与强权比肩。"
    },
    {
     "speaker": "阿木",
     "cue": "",
     "text": "可那恶人狰狞眉眼，刻在心底岁岁难删。"
    },
    {
     "speaker": "阿木",
     "cue": "",
     "text": "此生难忘血债深缘，不负父志，不负青山。"
    },
    {
     "speaker": "阿木",
     "cue": "",
     "text": "（阿木拔出腰间的彝刀，刀锋在火光下泛着寒光。）"
    },
    {
     "speaker": "阿木",
     "cue": "",
     "text": "阿果，我要替阿爹报仇！我要去找红军——就算它只是山外传来的一个传说！"
    },
    {
     "speaker": "阿木",
     "cue": "",
     "text": "（舞台光影明暗分割。远方高空亮起清冷苍茫白光。不是真的队伍——那是北边商旅传唱的一支红军歌谣，遥遥传来。）"
    }
   ],
   "stage": [
    "阿木",
    "（嘶吼）"
   ],
